package com.careerguidance.controller;
import com.careerguidance.dto.request.CreateQuestionRequest; import com.careerguidance.entity.*; import com.careerguidance.exception.QuestionNotFoundException; import com.careerguidance.repository.*; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/questions") @PreAuthorize("hasRole('ADMIN')") public class AssessmentManagementController {private final AssessmentQuestionRepository questions;private final AssessmentCategoryRepository categories;public AssessmentManagementController(AssessmentQuestionRepository q,AssessmentCategoryRepository c){questions=q;categories=c;}private AssessmentQuestion find(Long id){return questions.findById(id).orElseThrow(()->new QuestionNotFoundException(id));}private void assign(AssessmentQuestion q,CreateQuestionRequest r){q.setCategory(categories.findByName(r.getCategory()).orElseThrow(()->new IllegalArgumentException("Assessment category not found")));q.setQuestion(r.getQuestion());q.setQuestionType(r.getQuestionType());q.setDisplayOrder(r.getDisplayOrder());q.setDifficulty(r.getDifficulty());}
 @GetMapping public List<AssessmentQuestion> all(){return questions.findAll();} @PostMapping public AssessmentQuestion create(@Valid @RequestBody CreateQuestionRequest r){AssessmentQuestion q=new AssessmentQuestion();assign(q,r);q.setIsActive(true);return questions.save(q);}@PutMapping("/{id}") public AssessmentQuestion update(@PathVariable Long id,@Valid @RequestBody CreateQuestionRequest r){AssessmentQuestion q=find(id);assign(q,r);return questions.save(q);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){questions.delete(find(id));}@PatchMapping("/{id}/enable") public AssessmentQuestion enable(@PathVariable Long id){AssessmentQuestion q=find(id);q.setIsActive(true);return questions.save(q);}@PatchMapping("/{id}/disable") public AssessmentQuestion disable(@PathVariable Long id){AssessmentQuestion q=find(id);q.setIsActive(false);return questions.save(q);}}
